scriptdefs
= RustboroCity_Gym_EventScript_Marc
trainerbattle_single TRAINER_MARC RustboroCity_Gym_Text_MarcIntro RustboroCity_Gym_Text_MarcDefeat
msgbox	Ich muss unserer LEITERIN Anerkennung zollen.Es brauchte Köpfchen und Gespür, dass sie sich in ihrem jungen Alter für den GESTEIN-Typ entschieden hat.
end
= RustboroCity_Gym_EventScript_GymGuide
lock
faceplayer
goto_if_set FLAG_DEFEATED_RUSTBORO_GYM RustboroCity_Gym_EventScript_GymGuidePostVictory
msgbox	Yo, wie läuft's?Hör zu, mein Freund! Möchtest du CHAMP werden?Ich bin selbst kein TRAINER, nicht ich, aber ich kann dir sicher gewinnbringende Tipps geben.Dann ist das ja geklärt! Wir peilen gemeinsam die POKéMON-MEISTERSCHAFT an!Es ist deine Aufgabe als TRAINER, ORDEN zu sammeln, richtig?Aber ARENALEITER sind kein leichtes Ziel!Und genau da komme ich ins Spiel! Ich liefere dir Expertentipps!ROXANNE, die ARENALEITERIN, setzt auf GESTEIN-POKéMON.Der GESTEIN-Typ ist sehr widerstandsfähig, kann aber WASSER- und PFLANZE-Attacken nicht ab.Komm danach nochmal zu mir, wenn du die ARENALEITERIN besiegt hast.Na los, worauf wartest du!
release
end
= RustboroCity_Gym_EventScript_GymGuidePostVictory
msgbox	Whoa! Was für ein atemberaubender Sieg! Mein Anfeuern hat wohl gewirkt!Super! Sieh dir deinen TRAINERPASS an.Der GESTEINSORDEN, den du bekommen hast, sollte darauf ordentlich vermerkt sein.Mit anderen Worten…Du hast die erste Stufe der Treppe zur MEISTERSCHAFT erklommen!Das muss sich toll anfühlen!
release
end
= RustboroCity_Gym_EventScript_Tommy
trainerbattle_single TRAINER_TOMMY RustboroCity_Gym_Text_TommyIntro RustboroCity_Gym_Text_TommyDefeat
msgbox	ROXANNE ist um ein Vielfaches stärker als ich.Du solltest lieber auf der Hut sein!
end
= RustboroCity_Gym_EventScript_Josh
trainerbattle_single TRAINER_JOSH RustboroCity_Gym_Text_JoshIntro RustboroCity_Gym_Text_JoshDefeat
msgbox	Du hast die furchteinflößende Kraft des GESTEIN-Typs noch nicht mal ansatzweise gesehen!
end
= RustboroCity_Gym_EventScript_Roxanne
trainerbattle_single TRAINER_ROXANNE_1 RustboroCity_Gym_Text_RoxanneIntro RustboroCity_Gym_Text_RoxanneDefeat RustboroCity_Gym_EventScript_RoxanneDefeated NO_MUSIC
specialvar VAR_RESULT ShouldTryRematchBattle
goto_if_eq VAR_RESULT TRUE RustboroCity_Gym_EventScript_RoxanneRematch
goto_if_unset FLAG_RECEIVED_TM_ROCK_TOMB RustboroCity_Gym_EventScript_GiveRockTomb
msgbox	Weil du so stark bist, solltest du dich auch anderen ARENALEITERN stellen.Wenn du gegen viele TRAINER kämpfst, lernst du eine Menge dazu.
release
end
= RustboroCity_Gym_EventScript_GiveRockTomb
giveitem ITEM_TM_ROCK_TOMB
goto_if_eq VAR_RESULT FALSE Common_EventScript_ShowBagIsFull
setflag FLAG_RECEIVED_TM_ROCK_TOMB
msgbox	Diese TECHNISCHE MASCHINE, TM39, enthält GESTEINSGRAB.Sie fügt nicht nur Schaden durch fallende Felsen zu, sie senkt auch die INITIATIVE.Wenn du ein TM benutzt, lernt ein POKéMON die Attacke sofort.Denk daran, ein TM kann nur einmal verwendet werden, also überleg vorher gut.
release
end
= RustboroCity_Gym_EventScript_RoxanneRematch
trainerbattle_rematch_double TRAINER_ROXANNE_1 RustboroCity_Gym_Text_RoxannePreRematch RustboroCity_Gym_Text_RoxanneRematchDefeat RustboroCity_Gym_Text_RoxanneRematchNeedTwoMons
msgbox	ROXANNE: Ich habe noch viel zu lernen, wenn es um POKéMON-Kämpfe geht.Gerade dieses Bewusstsein lässt mich das Kämpfen umso mehr lieben!
end
= RustboroCity_Gym_EventScript_RoxanneDefeated
msgbox	PLAYER hat von ROXANNE den GESTEINSORDEN erhalten.
waitmessage
call Common_EventScript_PlayGymBadgeFanfare
msgbox	Der GESTEINSORDEN erhöht den ANGRIFFS-Wert deiner POKéMON.Außerdem können sie damit die VM-Attacke SCHNEIDER außerhalb von Kämpfen einsetzen.Bitte nimm das hier auch noch mit.
setflag FLAG_DEFEATED_RUSTBORO_GYM
setflag FLAG_BADGE01_GET
setvar VAR_RUSTBORO_CITY_STATE 1
addvar VAR_PETALBURG_GYM_STATE 1
setvar VAR_0x8008 1
call Common_EventScript_SetGymTrainers
call_if_eq VAR_PETALBURG_GYM_STATE 6 Common_EventScript_ReadyPetalburgGymForBattle
goto RustboroCity_Gym_EventScript_GiveRockTomb
end
